export const translation=[.4,-.2,.5];
export const points={origin:[0,0,0],x:[.1,0,0],y:[0,.1,0],z:[0,0,.1],target:[.1,.2,1]};
// Hand-derived correspondences from the article, not generated by the implementation under test.
export const fixtures={origin:[.4,-.2,.5],x:[.4,-.1,.5],y:[.3,-.2,.5],z:[.4,-.2,.6],target:[.2,-.1,1.5]};
export const labels={origin:'测 C 原点',x:'沿 C 的 x 走 10 cm',y:'沿 C 的 y 走 10 cm',z:'沿 C 的 z 走 10 cm',target:'测原来的目标点',roundtrip:'做正向—逆向往返'};
export const faults=['transpose','translation','scale'];
const add=(a,b)=>a.map((v,i)=>v+b[i]);
export const correct=p=>add([-p[1],p[0],p[2]],translation);
export function observed(p,fault) {
  if(fault==='transpose')return add([p[1],-p[0],p[2]],translation);
  if(fault==='translation')return add(correct(p),[.1,0,0]);
  if(fault==='scale')return correct(p.map(v=>1000*v));
  if(fault==='none')return correct(p);
  throw new Error('unknown case');
}
export function inverse(p,fault) {
  const t=fault==='translation'?add(translation,[.1,0,0]):translation;
  const q=p.map((v,i)=>v-t[i]);
  if(fault==='transpose')return [-q[1],q[0],q[2]];
  const result=[q[1],-q[0],q[2]];
  return fault==='scale'?result.map(v=>v/1000):result;
}
export const near=(a,b)=>a.every((v,i)=>Math.abs(v-b[i])<1e-8);
export function evidence(key,fault) {
  if(key==='roundtrip')return {key,input:points.target,expected:points.target,actual:inverse(observed(points.target,fault),fault),space:'C'};
  if(!points[key])throw new Error('unknown probe');
  return {key,input:points[key],expected:fixtures[key],actual:observed(points[key],fault),space:'B'};
}
export function candidates(records) {
  return faults.filter(f=>records.every(r=>near(evidence(r.key,f).actual,r.actual)));
}
export function regression(fault) {return Object.entries(points).map(([key,p])=>({key,pass:near(observed(p,fault),fixtures[key])}));}
